sys_script_include.script:
var BudgetUtilsClient = Class.create();
BudgetUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    approveBudget: function() {
        var budgetId = this.getParameter('sysparm_budgetId');

        var gr = new GlideRecord('x_1790227_event_ma_budget');
        if (gr.get(budgetId)) {
            gr.u_status = 'approved';
            gr.update();

            gs.eventQueue('x_1790227_event_ma.cancel.notify', gr, gr.assigned_to, gr.sys_id);
            return 'success';
        }
        return 'failure';
    },


// 1. Calculate total budget
    getTotalBudgetByEvent: function() {
        var eventID = this.getParameter('sysparm_event_id');
        var gr = new GlideAggregate('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventID);
        gr.addAggregate('SUM', 'u_total_budget');
        gr.query();
        while (gr.next()) {
            return 'Total Budget: ' + gr.getAggregate('SUM', 'u_total_budget');
        }
        return 'No budget records found';
    },

    // 2. Check if budget is approved
    isBudgetApproved: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventId);
        gr.addQuery('u_status', 'approved'); 
        gr.query();
		while(gr.next()){
        return 'budget is approved' ;
		}
		return 'budget is not approved';
    },

    // 3. Fetch budget details
    getBudgetDetailsByEventId: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                'Amount: ' + gr.getValue('u_total_budget') +
                ', Status: ' + gr.getValue('u_status') +
                ', Description: ' + gr.getValue('u_description')
            );
        }
        return result.length ? result.join('\n') : 'No budget details found';
    },

    type: 'BudgetUtilsClient'
});
